```hcl
# Terraform: schedule regular ingestion of a Bedrock knowledge base data source.
# There is no Terraform resource that runs an ingestion job directly; trigger it on a
# schedule with EventBridge + Lambda calling bedrock-agent StartIngestionJob.
resource "aws_cloudwatch_event_rule" "<example_resource_name>" {
  name                = "bedrock-kb-sync"
  schedule_expression = "rate(1 day)"
}

resource "aws_cloudwatch_event_target" "<example_resource_name>" {
  rule = aws_cloudwatch_event_rule.<example_resource_name>.name
  arn  = aws_lambda_function.<example_lambda_name>.arn
}
```
